"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { useParams } from "next/navigation";


export default function MessagePage(){

  const supabase = createClient();

  const params = useParams();
  const slug = params.slug as string;


  const [groomer,setGroomer] = useState<any>(null);

  const [messages,setMessages] = useState<any[]>([]);

  const [text,setText] = useState("");

  const [loading,setLoading] = useState(true);



  useEffect(()=>{
    loadChat();
  },[]);



  async function loadChat(){


    const {data:groomerData,error} = await supabase
      .from("groomers")
      .select("*")
      .eq("slug",slug)
      .single();



    if(error){
      console.log(error);
      return;
    }



    setGroomer(groomerData);



    const {data:messageData}=await supabase
      .from("messages")
      .select("*")
      .eq("groomer_id",groomerData.id)
      .order("created_at",{ascending:true});



    setMessages(messageData || []);

    setLoading(false);


  }






  async function sendMessage(){


    if(!text.trim()) return;



    if(!groomer) return;



    const {error}=await supabase
      .from("messages")
      .insert({

        groomer_id:groomer.id,

        sender_type:"customer",

        message:text

      });



    if(error){

      alert(error.message);
      return;

    }



    setText("");

    loadChat();


  }






  if(loading){

    return (
      <div className="p-10">
        Loading chat...
      </div>
    )

  }







  return (

    <main className="min-h-screen bg-green-50 p-6">


      <div className="max-w-xl mx-auto bg-white rounded-3xl shadow p-6">


        <h1 className="text-3xl font-bold text-green-700">

          💬 {groomer.business_name}

        </h1>




        <div className="h-96 overflow-y-auto mt-5 space-y-3 border rounded-xl p-4">


          {messages.map((msg)=>(

            <div
              key={msg.id}
              className={`p-3 rounded-xl ${
                msg.sender_type==="customer"
                ? "bg-green-100 text-right"
                : "bg-gray-100"
              }`}
            >

              {msg.message}


            </div>

          ))}



          {messages.length===0 && (

            <p className="text-gray-400 text-center">
              Start the conversation 🐾
            </p>

          )}



        </div>






        <div className="flex gap-2 mt-5">


          <input

            className="border rounded-xl p-3 flex-1"

            placeholder="Type message..."

            value={text}

            onChange={(e)=>setText(e.target.value)}

            onKeyDown={(e)=>{

              if(e.key==="Enter")
                sendMessage();

            }}

          />



          <button

            onClick={sendMessage}

            className="bg-green-600 text-white px-5 rounded-xl"

          >

            Send

          </button>


        </div>



      </div>


    </main>

  )


}